import java.text.Normalizer;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * What the user is looking for: a free-text name filter and a set of statuses.
 *
 * <p>This is a backend concern, not a UI one: {@link CustomerRepository} applies
 * it while paging and counting, so the grid never has to see more than the page
 * it shows.
 *
 * @param name     whitespace-separated terms; every term must occur in the first
 *                 or the last name. Blank matches every customer.
 * @param statuses the statuses to keep; empty matches every customer.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name.trim();
        // EnumSet keeps the statuses in declaration order, which is the order
        // they appear in the URL.
        statuses = (statuses == null || statuses.isEmpty())
                ? Collections.emptySet()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    public CustomerFilter(String name) {
        this(name, Set.of());
    }

    /** True when this filter keeps every customer. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name filter split into terms; empty when nothing was typed. */
    public List<String> terms() {
        return name.isEmpty() ? List.of()
                : Arrays.stream(WHITESPACE.split(name)).filter(term -> !term.isEmpty()).toList();
    }

    /**
     * This filter as a predicate. The terms are folded once, up front, so that
     * matching a page costs one fold per customer.
     */
    public Predicate<Customer> asPredicate() {
        List<String> foldedTerms = terms().stream().map(CustomerFilter::fold).toList();
        Set<CustomerStatus> wanted = statuses;
        return customer -> {
            if (!wanted.isEmpty() && !wanted.contains(customer.status())) {
                return false;
            }
            if (foldedTerms.isEmpty()) {
                return true;
            }
            String firstName = fold(customer.firstName());
            String lastName = fold(customer.lastName());
            return foldedTerms.stream()
                    .allMatch(term -> firstName.contains(term) || lastName.contains(term));
        };
    }

    /** True when this filter keeps the given customer. */
    public boolean matches(Customer customer) {
        return asPredicate().test(customer);
    }

    /**
     * Case- and accent-insensitive form of a piece of text, so that
     * {@code makinen}, {@code MAKINEN} and {@code mäkinen} all look the same.
     */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
