+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** The matching rules, without a UI in the way. */
+class CustomerFilterTest {
+
+    private static final Customer ADA =
+            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            2, "Joséphine", "Mäkinen", "j@example.com", "France", CustomerStatus.CLOSED);
+
+    @Test
+    void anEmptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.EMPTY.matches(ADA));
+        assertTrue(CustomerFilter.EMPTY.matches(JOSEPHINE));
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(new CustomerFilter("   ").isEmpty());
+    }
+
+    @Test
+    void everyTermMustMatchAName() {
+        assertTrue(new CustomerFilter("ada aal").matches(ADA));
+        assertTrue(new CustomerFilter("aal ada").matches(ADA));
+        assertTrue(new CustomerFilter("  ada    aal  ").matches(ADA));
+        assertFalse(new CustomerFilter("ada virtanen").matches(ADA));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccents() {
+        for (String typed : List.of("mäkinen", "makinen", "MAKINEN", "MäKiNeN")) {
+            assertTrue(new CustomerFilter(typed).matches(JOSEPHINE), typed);
+        }
+        assertTrue(new CustomerFilter("josephine").matches(JOSEPHINE));
+        assertTrue(new CustomerFilter("joséphine").matches(JOSEPHINE));
+    }
+
+    @Test
+    void statusesAreKeptInDeclarationOrder() {
+        CustomerFilter filter = new CustomerFilter(
+                "", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                List.copyOf(filter.statuses()));
+        assertTrue(filter.matches(ADA));
+        assertTrue(filter.matches(JOSEPHINE));
+        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.PENDING)).matches(ADA));
+    }
+
+    @Test
+    void bothHalvesMustMatch() {
+        assertTrue(new CustomerFilter("ada", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
+        assertFalse(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)).matches(ADA));
+        assertFalse(new CustomerFilter("zzz", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
+    }
+}
