+/**
+ * The half of the behaviour a browserless test cannot see: what the address bar
+ * says, and what typing costs the backend.
+ *
+ * <p>Deliberately not named {@code *Test}, so that {@code mvn test} stays pure
+ * JVM. Run it with
+ * {@code mvn -o test -Dtest=CustomerListViewBrowserIT -DfailIfNoSpecifiedTests=false}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    /** Customers whose name contains "vir". */
+    private static final int VIR = 15;
+
+    /** Of those, the ones that are ACTIVE or CLOSED. */
+    private static final int VIR_ACTIVE_OR_CLOSED = 10;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingFiltersTheGridWithoutFloodingTheBackend() {
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertEquals(getUrl() + "/", page.url());
+
+        int historyBefore = historyLength();
+        queryLog.clear();
+
+        nameFilter().getInputLocator()
+                .pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(40));
+        assertThat(summary()).hasText("Showing 15 of 500");
+
+        assertEquals(15, grid().getTotalRowCount());
+        assertEquals(getUrl() + "/?name=virtanen", page.url());
+        assertEquals(historyBefore, historyLength(),
+                "typing must not push a history entry per keystroke");
+
+        int queries = queryLog.countQueries().size() + queryLog.pageQueries().size();
+        assertTrue(queries <= 3, "typing eight letters cost " + queries + " queries: "
+                + queryLog.countQueries() + " " + queryLog.pageQueries());
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "typing pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void bothFiltersAreInTheUrl() {
+        statusFilter().selectItem("ACTIVE");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+        statusFilter().selectItem("CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+        statusFilter().close();
+
+        assertEquals(getUrl() + "/?status=ACTIVE,CLOSED", page.url());
+
+        nameFilter().setValue("vir");
+        assertThat(summary()).hasText("Showing " + VIR_ACTIVE_OR_CLOSED + " of 500");
+        assertEquals(getUrl() + "/?name=vir&status=ACTIVE,CLOSED", page.url());
+        assertEquals(VIR_ACTIVE_OR_CLOSED, grid().getTotalRowCount());
+    }
+
+    @Test
+    void aTwoTermFilterSurvivesTheUrl() {
+        nameFilter().setValue("ada aal");
+        assertThat(summary()).hasText("Showing 2 of 500");
+
+        page.navigate(page.url());
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        nameFilter().assertValue("ada aal");
+        assertThat(summary()).hasText("Showing 2 of 500");
+    }
+
+    @Test
+    void anEmptyFilterLeavesNothingInTheUrl() {
+        nameFilter().setValue("vir");
+        assertThat(summary()).hasText("Showing " + VIR + " of 500");
+        assertEquals(getUrl() + "/?name=vir", page.url());
+
+        nameFilter().setValue("");
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertEquals(getUrl() + "/", page.url());
+    }
+
+    @Test
+    void aFilteredUrlOpensFiltered() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        nameFilter().assertValue("vir");
+        assertEquals("ACTIVE, CLOSED", statusFilter().getValue());
