+    /** Counts matching customers straight from the CSV, as a cross-check. */
+    private int countMatching(java.util.function.Predicate<String> nameTest,
+            CustomerStatus... statuses) {
+        List<String> lines = csvLines();
+        Set<CustomerStatus> wanted = Set.of(statuses);
+        return (int) lines.stream().filter(line -> {
+            String[] c = line.split(",", -1);
+            String fullName = c[1] + " " + c[2];
+            return nameTest.test(fullName)
+                    && (wanted.isEmpty() || wanted.contains(CustomerStatus.valueOf(c[5])));
+        }).count();
+    }
+
+    private static List<String> csvLines() {
+        try (var in = CustomerRepository.class.getResourceAsStream("/customers.csv")) {
+            var reader = new java.io.BufferedReader(
+                    new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8));
+            return reader.lines().skip(1).filter(line -> !line.isBlank()).toList();
+        } catch (java.io.IOException e) {
+            throw new java.io.UncheckedIOException(e);
+        }
+    }
